#!/usr/bin/env bash
#
# MBA Journey — installer / updater for mba.maxxcom.in
# Run from your laptop (same server as MediScan):
#
#   ssh -i ~/.ssh/axm_deploy root@mediscan.maxxcom.in 'bash -s' < install-mba.sh
# or, in the server's own terminal (e.g. Hostinger's browser terminal):
#   bash <(curl -fsSL <raw URL of this file>)
# It asks for the MBA password (or set MBA_PASS=... beforehand). Username defaults to prime.
#
# Safe to run again for updates: it only touches /var/www/mba and the
# mba.maxxcom.in nginx site. It never touches MediScan or other sites.
set -euo pipefail
DOMAIN="${DOMAIN:-mba.maxxcom.in}"
VERSION="20261118053643"
ROOT=/var/www/mba
say(){ printf '\n\033[1m%s\033[0m\n' "$*"; }
die(){ printf '\n\033[31mERROR: %s\033[0m\n' "$*" >&2; exit 1; }

[ "$(id -u)" = 0 ] || die "run as root"
command -v nginx >/dev/null || die "nginx is not installed"

say "1/5  Installing site files (version $VERSION)"
mkdir -p "$ROOT/releases/$VERSION"
echo "" | base64 -d | tar -xzf - -C "$ROOT/releases/$VERSION"
chmod -R a+rX "$ROOT"
ln -sfn "$ROOT/releases/$VERSION" "$ROOT/current.new" && mv -Tf "$ROOT/current.new" "$ROOT/current"
# login gate: gate_1 = the app, gate_0 = login only
ln -sfn "$ROOT/current" "$ROOT/gate_1"
mkdir -p "$ROOT/gate_0"
cp "$ROOT/current/login.html" "$ROOT/gate_0/login.html"
printf '%s\n' '<!DOCTYPE html><meta charset="utf-8"><meta name="robots" content="noindex"><meta http-equiv="refresh" content="0;url=/login.html"><title>Sign in</title><script>location.replace("/login.html")</script><a href="/login.html">Sign in</a>' > "$ROOT/gate_0/index.html"
chmod -R a+rX "$ROOT"
# keep the 3 most recent releases
# (sorted by version name; never the live one)
LIVE=$(readlink -f "$ROOT/current")
ls -1d "$ROOT"/releases/* | sort -r | tail -n +4 | while read -r d; do [ "$(readlink -f "$d")" = "$LIVE" ] || rm -rf "$d"; done

say "2/5  nginx site for $DOMAIN"
if [ -d /etc/nginx/sites-available ]; then CONF=/etc/nginx/sites-available/$DOMAIN; LINK=/etc/nginx/sites-enabled/$DOMAIN; else CONF=/etc/nginx/conf.d/$DOMAIN.conf; LINK=""; fi
if [ -f "$CONF" ] && [ "${REWRITE_NGINX:-0}" != 1 ]; then
  echo "Keeping existing $CONF (rerun with REWRITE_NGINX=1 to replace it)."
else
  [ -f "$CONF" ] && cp "$CONF" "$CONF.bak.$(date +%s)"
  # The login token is computed here from the username/password; neither is stored.
  MBA_USER="${MBA_USER:-prime}"
  if [ -z "${MBA_PASS:-}" ]; then
    if [ -r /dev/tty ]; then printf 'Choose the MBA password for user "%s": ' "$MBA_USER" > /dev/tty; IFS= read -rs MBA_PASS < /dev/tty; echo > /dev/tty; fi
  fi
  [ -n "${MBA_PASS:-}" ] || die "no password given (set MBA_PASS=... or run interactively)"
  TOKEN=$(printf '%s' "$DOMAIN|$(printf '%s' "$MBA_USER" | tr '[:upper:]' '[:lower:]')|$MBA_PASS" | sha256sum | cut -d' ' -f1)
  echo "" | base64 -d | sed -e "s/__DOMAIN__/$DOMAIN/g" -e "s/__TOKEN__/$TOKEN/" > "$CONF"
  unset MBA_PASS TOKEN
  [ -n "$LINK" ] && ln -sfn "$CONF" "$LINK"
fi
nginx -t || die "nginx config test failed — nothing reloaded"
{ systemctl reload nginx 2>/dev/null && systemctl is-active --quiet nginx; } || nginx -s reload

say "3/5  HTTPS"
if grep -q "listen 443" "$CONF" 2>/dev/null; then
  echo "HTTPS already configured."
elif command -v certbot >/dev/null; then
  if certbot --nginx -d "$DOMAIN" --non-interactive --agree-tos --redirect --register-unsafely-without-email; then
    echo "HTTPS enabled."
  else
    echo "Could not get a certificate yet. Most likely DNS for $DOMAIN doesn't point to this server."
    echo "Add a DNS record:  mba  CNAME  mediscan.maxxcom.in   (or an A record to this server's IP), wait a few minutes, then run this installer again."
  fi
else
  echo "certbot not found — install it (apt install certbot python3-certbot-nginx) and run again for HTTPS."
fi

say "4/5  MBA Login button on maxxcom.in"
if [ "${MAXXCOM_LINK:-1}" = 1 ] && command -v python3 >/dev/null; then
  echo "" | base64 -d > /tmp/mba_maxxcom_link.py
  python3 /tmp/mba_maxxcom_link.py || echo "Could not add the button (site unchanged)."
  rm -f /tmp/mba_maxxcom_link.py
else
  echo "Skipped (MAXXCOM_LINK=0 or python3 missing)."
fi

say "5/5  Check"
body=$(curl -s -H "Host: $DOMAIN" http://127.0.0.1/ || true)
if echo "$body" | grep -q "login.html"; then echo "Login gate OK: visitors without a valid login only get the sign-in page."; else echo "WARNING: unexpected response from the site — check the nginx config."; fi
echo
echo "Done. Open https://$DOMAIN  (username: prime)"
